INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(9216, 0, 0, '%s goes into a frenzy!', 16, 0, 100, 0, 0, 0, 'Spirestone Warlord'),
(9259, 0, 0, '%s goes into a frenzy!', 16, 0, 100, 0, 0, 0, 'Firebrand Grunt'),
(9268, 0, 0, '%s goes into a frenzy!', 16, 0, 100, 0, 0, 0, 'Smolderthorn Berserker'),
(9716, 0, 0, '%s becomes enraged!', 16, 0, 100, 0, 0, 0, 'Bloodaxe Warmonger'),
(10162, 15, 0, 'Get up, little red wyrm...and destroy them!\n', 14, 0, 100, 0, 0, 0, 'Lord Victor Nefarius'),
(10296, 0, 0, 'At last - one among you is worthy of my knowledge. Worry not - I have probed your thoughts, no harm will come to you.', 12, 0, 100, 1, 0, 0, 'Vaelan'),
(10296, 1, 0, 'Listen carefully, for the lord of Blackrock will surely destroy you, should you not be prepared.', 12, 0, 100, 1, 0, 0, 'Vaelan'),
(10296, 2, 0, '%s is surrounded by a barrier of anti-magic.', 16, 0, 100, 0, 0, 0, 'Vaelan'),
(10296, 3, 0, 'I have discerned the path that you must take. Are you prepared?', 12, 0, 100, 1, 0, 0, 'Vaelan'),
(10299, 0, 0, 'Begone, mortal. You are not worthy of my knowledge.', 15, 0, 100, 0, 0, 0, 'Scarshield Infiltrator'),
(10317, 0, 0, 'We''re doomed!', 14, 0, 100, 0, 0, 0, 'Blackhand elite'),
(10740, 0, 0, '%s whimpers.', 16, 0, 100, 0, 0, 0, 'Awbee'),
(10740, 0, 1, '%s breathes erratically.', 16, 0, 100, 0, 0, 0, 'Awbee'),
(10740, 0, 2, '%s cries for help.', 16, 0, 100, 0, 0, 0, 'Awbee'),
(10776, 0, 0, 'Leaping leper gnomes! I''ve been stuck in there for months. Thanks, gang.', 12, 0, 100, 0, 0, 0, 'Finkle Einhorn'),
(10799, 0, 3, '%s cries.', 16, 0, 100, 0, 0, 0, 'Warosh'),
(10799, 1, 0, 'Hahah!  Revenge is mine!', 14, 0, 100, 0, 0, 0, 'Warosh'),
(10799, 2, 0, 'Rawww!  Urok is dead!!  Hahah!!', 14, 0, 100, 0, 0, 0, 'Warosh'),
(10799, 3, 0, 'Revenge is mine!', 12, 0, 100, 0, 0, 0, 'Warosh'),
(16042, 0, 0, '%s goes into a frenzy!', 16, 0, 100, 0, 0, 0, 'Lord Valthalak - Cast Frenzy');
