-- Lower Blackrock Spire: SmartAI and creature texts the dungeon was missing. Source: 3.3.5 or 4.3.4, whichever has more rows for the creature
-- (the two sets agree where both exist; the dungeon was re-levelled by Cataclysm). Columns are identical to SkyFire's. event_flags are kept, minus the 4.3.4
-- WHILE_CHARMED bit (0x200), which is the 40-man difficulty bit in SkyFire. Every spell used was checked against the 5.4.8 spell data.
-- Creatures with a C++ ScriptName keep it. Safe to run twice: DELETE before INSERT by key.

-- Enable SmartAI only where no C++ script is bound.
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (9098, 9197, 9198, 9199, 9200, 9201, 9216, 9217, 9239, 9240, 9241, 9257, 9258, 9259, 9260, 9261, 9262, 9263, 9264, 9265, 9266, 9267, 9268, 9269, 9583, 9692, 9693, 9708, 9716, 9717, 10083, 10261, 10263, 10299, 10317, 10318, 10319, 10366, 10371, 10372, 10374, 10375, 10376, 10442, 10447, 10509, 10740, 10776, 10799, 10814, 10899, 16044, 16048) AND `ScriptName` = '';

-- Texts missing in SkyFire (existing rows of the same entries are left alone).
DELETE FROM `creature_text` WHERE (`entry` = 9216 AND `groupid` = 0 AND `id` = 0) OR (`entry` = 9259 AND `groupid` = 0 AND `id` = 0) OR (`entry` = 9268 AND `groupid` = 0 AND `id` = 0) OR (`entry` = 9716 AND `groupid` = 0 AND `id` = 0) OR (`entry` = 10162 AND `groupid` = 15 AND `id` = 0) OR (`entry` = 10296 AND `groupid` = 0 AND `id` = 0) OR (`entry` = 10296 AND `groupid` = 1 AND `id` = 0) OR (`entry` = 10296 AND `groupid` = 2 AND `id` = 0) OR (`entry` = 10296 AND `groupid` = 3 AND `id` = 0) OR (`entry` = 10299 AND `groupid` = 0 AND `id` = 0) OR (`entry` = 10317 AND `groupid` = 0 AND `id` = 0) OR (`entry` = 10740 AND `groupid` = 0 AND `id` = 0) OR (`entry` = 10740 AND `groupid` = 0 AND `id` = 1) OR (`entry` = 10740 AND `groupid` = 0 AND `id` = 2) OR (`entry` = 10776 AND `groupid` = 0 AND `id` = 0) OR (`entry` = 10799 AND `groupid` = 0 AND `id` = 3) OR (`entry` = 10799 AND `groupid` = 1 AND `id` = 0) OR (`entry` = 10799 AND `groupid` = 2 AND `id` = 0) OR (`entry` = 10799 AND `groupid` = 3 AND `id` = 0) OR (`entry` = 16042 AND `groupid` = 0 AND `id` = 0);

-- Creature SmartAI rows.
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (9098, 9197, 9198, 9199, 9200, 9201, 9216, 9217, 9239, 9240, 9241, 9257, 9258, 9259, 9260, 9261, 9262, 9263, 9264, 9265, 9266, 9267, 9268, 9269, 9583, 9692, 9693, 9708, 9716, 9717, 10083, 10261, 10263, 10299, 10317, 10318, 10319, 10366, 10371, 10372, 10374, 10375, 10376, 10442, 10447, 10509, 10740, 10776, 10799, 10814, 10899, 16044, 16048);

-- Timed action lists called by the rows above.
DELETE FROM `smart_scripts` WHERE `source_type` = 9 AND `entryorguid` IN (1029900, 1029901);
